osest \"\n200\t                         \"canonical name (submit.py strips unknown names)\"\n201\t                         % (name, comp.strip(), components_path))\n202\t        # collect graph facts\n203\t        dl = fm.get(\"dependencies\")\n204\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n205\t            if isinstance(dl, list) else []\n206\t        is_branch[key] = \"BRANCH-\" in key\n207\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n208\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n209\t        it = fm.get(\"implementation_type\")\n210\t        itype[key] = it if it in IT_ENUM else None\n211\t        prio[key] = fm.get(\"priority\")\n212\t\n213\t    def kind(key):\n214\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n215\t        that is not type Implementation is never a parallel-rule party; an\n216\t        Implementation epic's kind is its implementation_type when that is a\n217\t        known label, else 'general'.\"\"\"\n218\t        if not is_impl[key]:\n219\t            return \"non-implementation\"\n220\t        return itype[key] or \"general\"\n221\t\n222\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n223\t    universe = [k for k in epics\n224\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n225\t    for k in sorted(epics):\n226\t        if not is_docs[k]:\n227\t            continue\n228\t        cl = dependency_closure(k, deps)\n229\t        missing = sorted(e for e in universe if e != k and e not in cl)\n230\t        if missing:\n231\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n232\t                         \"Implementation epic — add %s to its dependency chain\"\n233\t                         % (k, \", \".join(missing)))\n234\t\n235\t    # 4. Priority inheritance — enablers of P0 work must be P0\n236\t    for k in sorted(epics):\n237\t        if is_branch[k] or is_docs[k]:\n238\t            continue\n239\t        if prio.get(k) != \"P0\":\n240\t            continue\n241\t        # every main-plan, non-docs epic in k's closure enables P0 work\n242\t        cl = dependency_closure(k, deps)\n243\t        for t in sorted(cl):\n244\t            if is_branch[t] or is_docs[t]:\n245\t                continue\n246\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n247\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n248\t                             \"but is %s — raise it to P0 or restructure\"\n249\t                             % (t, prio.get(t), k, prio.get(t)))\n250\t\n251\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n252\t    #    pairs carry no dependencies edge in either direction (direct edges\n253\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n254\t    #    them; dependencies naming epics with no file cannot be judged).\n255\t    for k in sorted(epics):\n256\t        if kind(k) == \"docs-authoring\":\n257\t            continue\n258\t        for t in deps[k]:\n259\t            if t not in epics:\n260\t                continue\n261\t            pair = frozenset((kind(t), kind(k)))\n262\t            rule = PARALLEL_PAIRS.get(pair)\n263\t            if rule:\n264\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n265\t                             \"parallel; remove the dependencies edge and \"\n266\t                             \"express any coupling as an AC gate on the \"\n267\t                             \"dependent epic\"\n268\t                             % (rule, t, kind(t), k, kind(k)))\n269\t\n270\t    # 6. Epic-size overage triggers — an acknowledged above-guideline epic\n271\t    #    must carry a re-split trigger in the summary.\n272\t    probs.extend(check_oversize_trigger(artifacts_dir, strat_id))\n273\t    return probs\n274\t\n275\t\n276\t# ─── self-check ───────────────────────────────────────────────────────────────\n277\t\n278\tdef _self_check():\n279\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n280\t    import shutil\n281\t    import tempfile\n282\t\n283\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n284\t    try:\n285\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n286\t        os.makedirs(art)\n287\t        comp = os.path.join(tmp, \"components.txt\")\n288\t        with open(comp, \"w\") as f:\n289\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n290\t\n291\t        def write(name, fm, body):\n292\t            with open(os.path.join(art, name), \"w\") as f:\n293\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n294\t\n295\t        def write_raw(name, content):\n296\t            with open(os.path.join(art, name), \"w\") as f:\n297\t                f.write(content)\n298\t\n299\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n300\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n301\t        write(\"RHAISTRAT-9001-E001.md\",\n302\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n303\t              \"dependencies: []\\n\", good_body)\n304\t        write(\"RHAISTRAT-9001-E002.md\",\n305\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n306\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n307\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n308\t              good_body)\n309\t        # a konflux-onboarding epic parallel to the general epic (no edge\n310\t        # either way) is the Rule 10-compliant shape — must not be flagged\n311\t        write(\"RHAISTRAT-9001-E003.md\",\n312\t              \"component: Dashboard\\ntype: Implementation\\n\"\n313\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n314\t              \"dependencies: []\\n\", good_body)\n315\t        # good summary: a negated size affirmation carries no overage\n316\t        write_raw(\"RHAISTRAT-9001-decomposition.md\",\n317\t                  \"---\\nparent_strat: RHAISTRAT-9001\\n---\\n\"\n318\t                  \"# S\\nNo epic exceeds the ~2-week epic guideline; epic \"\n319\t                  \"sizes are sprint-appropriate.\\n\")\n320\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n321\t                     comp) == [], \"good fixture must pass cleanly\"\n322\t\n323\t        # good fixture 2: an acknowledged overage WITH a re-split trigger is\n324\t        # a managed trade-off — must not be flagged\n325\t        write(\"RHAISTRAT-9003-E001.md\",\n326\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n327\t              \"dependencies: []\\n\", good_body)\n328\t        write_raw(\"RHAISTRAT-9003-decomposition.md\",\n329\t                  \"---\\nparent_strat: RHAISTRAT-9003\\n---\\n\"\n330\t                  \"# S\\n## Health Warnings\\n- Epic size: E001 remains \"\n331\t                  \"slightly above the ~2-week epic guideline as one logical \"\n332\t                  \"change; re-split along tier lines if the audit finds \"\n333\t                  \"materially more sites than the estimate.\\n\")\n334\t        assert check(\"RHAISTRAT-9003\", os.path.join(tmp, \"artifacts\"),\n335\t                     comp) == [], \"triggered overage must pass cleanly\"\n336\t\n337\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n338\t        # Rule 10 konflux-onboarding -> general edge, bare overage note\n339\t        write(\"RHAISTRAT-9002-E001.md\",\n340\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n341\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n342\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n343\t              \"## HLR Traceability\\nh\\n\")\n344\t        write(\"RHAISTRAT-9002-E002.md\",\n345\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n346\t              \"dependencies: []\\n\", good_body)\n347\t        write(\"RHAISTRAT-9002-E003.md\",\n348\t              \"component: Dashboard\\ntype: Implementation\\n\"\n349\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n350\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n351\t        # E004 is a main-plan Implementation the docs epic never depends on\n352\t        write(\"RHAISTRAT-9002-E004.md\",\n353\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n354\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n355\t        write(\"RHAISTRAT-9002-E005.md\",\n356\t              \"component: Dashboard\\ntype: Implementation\\n\"\n357\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n358\t              \"dependencies: []\\n\", good_body)\n359\t        write_raw(\"RHAISTRAT-9002-decomposition.md\",\n360\t                  \"---\\nparent_strat: RHAISTRAT-9002\\n---\\n\"\n361\t                  \"# S\\n## Health Warnings\\n- Planning note (epic size): \"\n362\t                  \"E001 is ~1.5 sprints, slightly above the ~2-week epic \"\n363\t                  \"guideline; the boundary is kept; flagged for planning \"\n364\t                  \"awareness only.\\n\")\n365\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n366\t        joined = \"\\n\".join(probs)\n367\t        assert \"missing 'Scope'\" in joined, probs\n368\t        assert \"Model Serving Stack\" in joined, probs\n369\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n370\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n371\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n372\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n373\t        assert \"re-split trigger\" in joined, probs\n374\t        print(\"self-check OK: 6 checks fire on bad fixture, clean on good\")\n375\t        return 0\n376\t    finally:\n377\t        shutil.rmtree(tmp, ignore_errors=True)\n378\t\n379\t\n380\tdef main(argv=None):\n381\t    ap = argparse.ArgumentParser(description=__doc__)\n382\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n383\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n384\t    ap.add_argument(\"--components\",\n385\t                    default=\".context/rhai-components.txt\")\n386\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n387\t    args = ap.parse_args(argv)\n388\t\n389\t    if args.self_check:\n390\t        return _self_check()\n391\t    if not args.strat_id:\n392\t        ap.error(\"strat_id is required (unless --self-check)\")\n393\t\n394\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n395\t    if probs:\n396\t        for p in probs:\n397\t            print(\"VIOLATION: %s\" % p)\n398\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n399\t              \"complete\" % len(probs))\n400\t        return 1\n401\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n402\t    return 0\n403\t\n404\t\n405\tif __name__ == \"__main__\":\n406\t    sys.exit(main())\n407\t"}]},"parent_tool_use_id":"chatcmpl-tool-bc9990585c0fc227","agent_id":"a9ee74de494750547","session_id":"40ac0a95-f7b4-4f3c-bf55-b2c4e97b3f62","uuid":"72a477a0-f58e-4e1d-94d7-fd00f308932c","timestamp":"2026-10-25T18:12:57.540Z","tool_result_meta":[{"id":"chatcmpl-tool-af178261dad44ed4","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Decompose RHAISTRAT-8009"}
